func (q *Queries) UpdateCampaign(ctx context.Context, arg UpdateCampaignParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateCampaign,
		arg.ID,
		arg.Name,
		arg.DidID,
		arg.TimeZone,
		arg.CallingWindow,
		arg.DefaultCountryCode,
		arg.MaxConcurrent,
		arg.RingTimeoutSec,
		arg.RetryPolicy,
		arg.FollowUpQueueID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
